(function(){
  var box=document.querySelector('.transW .transP'); if(!box||typeof PuSet==='undefined') return;
  var page=(PuSet.gTranslate.pageLang||kLng).split('-')[0];
  var langs=String(PuSet.gTranslate.includedLangs||'').split(',').map(function(s){return s.trim()}).filter(Boolean);
  var dn=null; try{dn=new Intl.DisplayNames([kLng],{type:'language'})}catch(e){}
  function name(c){try{return dn?dn.of(c):c}catch(e){return c}}
  function own(c){try{return new Intl.DisplayNames([c],{type:'language'}).of(c)}catch(e){return ''}}
  function cur(){var m=document.cookie.match(/(?:^|;\s*)googtrans=\/[^\/]*\/([^;]+)/);return m?decodeURIComponent(m[1]):''}
  var sys=(navigator.language||'').toLowerCase(); sys=/^zh-(tw|hk|hant)/.test(sys)?'zh-TW':/^zh/.test(sys)?'zh-CN':sys.split('-')[0];
  var ul=document.createElement('ul'); ul.className='kTrL notranslate'; ul.setAttribute('role','listbox'); ul.setAttribute('translate','no');
  function li(code,label,extra,sep){var l=document.createElement('li');l.setAttribute('role','option');l.tabIndex=0;l.dataset.c=code;if(sep)l.className='sep';l.textContent=label;if(extra){var s=document.createElement('small');s.textContent=extra;l.appendChild(s)}ul.appendChild(l)}
  li('',kT('لغة الصفحة','Page language'),name(page));
  li(sys===page?'':sys,kT('لغة الجهاز','System language'),name(sys),true);
  langs.forEach(function(c){if(c.split('-')[0]!==page){var o=own(c),n=name(c);li(c,n,o&&o!==n?o:'')}});
  box.insertBefore(ul,box.firstChild);
  function mark(){var c=cur();if(c===page)c='';[].forEach.call(ul.children,function(l,i){var on=l.dataset.c===c&&(i!==1||c!=='');if(i===1&&c===''&&sys===page)on=false;l.classList.toggle('on',on);l.setAttribute('aria-selected',on)})}
  function wipe(){var h=location.hostname,d=['',h,'.'+h,'.'+h.split('.').slice(-2).join('.')];d.forEach(function(x){document.cookie='googtrans=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/'+(x?';domain='+x:'')})}
  function go(c){
    var t=document.getElementById('offTrans'); if(t) t.checked=false;
    if(!c||c===page){ if(cur()){wipe();location.reload()} mark(); return }
    var sel=document.querySelector('select.goog-te-combo');
